package com.bank.contract.ledger;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

// Holds balances and the core invariant: total money is conserved.
public class Ledger {
    private final Map<String, BigDecimal> balances = new HashMap<>();
    public void open(String id, BigDecimal bal) { balances.put(id, bal); }
    public void debit(String id, BigDecimal amt) { balances.merge(id, amt.negate(), BigDecimal::add); }
    public void credit(String id, BigDecimal amt) { balances.merge(id, amt, BigDecimal::add); }
    public BigDecimal balance(String id) { return balances.get(id); }
    public BigDecimal total() { return balances.values().stream().reduce(BigDecimal.ZERO, BigDecimal::add); }
}
