package com.bank.contract.idempotency;

import java.util.concurrent.ConcurrentHashMap;

// Guarantees a transfer id is processed at most once (duplicate-delivery contract).
public class IdempotencyStore {
    private final ConcurrentHashMap<String, Boolean> seen = new ConcurrentHashMap<>();
    // Returns true only the FIRST time this id is claimed.
    public boolean claimFirstTime(String transferId) {
        return seen.putIfAbsent(transferId, Boolean.TRUE) == null;
    }
}
