package com.bank.contract.outbox;

import java.util.ArrayList;
import java.util.List;

// Events are written here in the SAME step as the ledger change.
// If the broker is down, events wait here and are published on recovery (no loss).
public class EventOutbox {
    public static final class Entry { public final String payload; public boolean published;
        Entry(String p) { this.payload = p; } }
    private final List<Entry> entries = new ArrayList<>();
    public synchronized void write(String payload) { entries.add(new Entry(payload)); }
    public synchronized int publishPending(boolean brokerUp) {
        int n = 0;
        if (!brokerUp) return 0;                 // broker down → nothing published, nothing lost
        for (Entry e : entries) if (!e.published) { e.published = true; n++; }
        return n;
    }
    public synchronized long unpublished() { return entries.stream().filter(e -> !e.published).count(); }
    public synchronized int total() { return entries.size(); }
}
