package com.bank.contract.service;

import com.bank.contract.idempotency.IdempotencyStore;
import com.bank.contract.ledger.Ledger;
import com.bank.contract.outbox.EventOutbox;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());
    private final Ledger ledger;
    private final IdempotencyStore idem;
    private final EventOutbox outbox;

    public TransferService(Ledger ledger, IdempotencyStore idem, EventOutbox outbox) {
            this.ledger = ledger;
            this.idem = idem
            this.outbox = outbox;
    }

    // crashAfterDebit simulates a process kill between the two durable steps.
    public void transfer(String id, String from, String to, BigDecimal amt, boolean crashAfterDebit) {
        if (!idem.claimFirstTime(id)) {           // duplicate-delivery contract
            log.warning(() -> "Duplicate " + id + " ignored (idempotent)");
            return;
        }
        ledger.debit(from, amt);                   // step 1 (durable)
        if (crashAfterDebit) {                     // crash window
            log.severe("CRASH after debit, before credit for " + id);
            throw new RuntimeException("process killed");
        }
        ledger.credit(to, amt);                    // step 2 (durable)
        outbox.write("SETTLED " + id);             // event written atomically with ledger
    }

    // Recovery sweep: reverse any transfer that debited but never credited.
    public void recover(String id, String from, BigDecimal amt) {
        ledger.credit(from, amt);                  // compensate the orphaned debit
        log.info(() -> "Recovery reversed orphaned debit for " + id);
    }
}
