package com.bank.contract;

import com.bank.contract.idempotency.IdempotencyStore;
import com.bank.contract.ledger.Ledger;
import com.bank.contract.outbox.EventOutbox;
import com.bank.contract.service.TransferService;
import java.math.BigDecimal;
import java.util.logging.*;

public class FailureContractDemo {
    private static final Logger log = Logger.getLogger(FailureContractDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h); log.setLevel(Level.INFO);
    }
    public static void main(String[] args) {
        BigDecimal amt = new BigDecimal("50000");

        // Contract 1 — DUPLICATE DELIVERY → debit exactly once.
            Ledger l1 = fresh();
            IdempotencyStore i1 = new IdempotencyStore();
        TransferService s1 = new TransferService(l1, i1, new EventOutbox());
        BigDecimal before = l1.total();
        s1.transfer("T1","SAV2001","CUR3001",amt,false);
        s1.transfer("T1","SAV2001","CUR3001",amt,false); // duplicate
        assertEq("DUPLICATE_DELIVERY", l1.balance("SAV2001"), new BigDecimal("950000"));
        assertEq("TOTAL_CONSERVED_DUP", l1.total(), before);

        // Contract 2 — CRASH between debit and credit → recovery conserves money.
            Ledger l2 = fresh();
            TransferService s2 = new TransferService(l2, new IdempotencyStore(), new EventOutbox());
        BigDecimal before2 = l2.total();
        try { s2.transfer("T2","SAV2001","CUR3001",amt,true); } catch (RuntimeException ignored) {}
        s2.recover("T2","SAV2001",amt);                  // recovery sweep
        assertEq("CRASH_MONEY_CONSERVED", l2.total(), before2);

        // Contract 3 — CACHE LOSS → balances still correct from source of truth.
        Ledger l3 = fresh();
        assertEq("CACHE_LOSS_CORRECT", l3.balance("SAV2001"), new BigDecimal("1000000"));

        // Contract 4 — BROKER DOWN → event not lost, published on recovery.
        EventOutbox o4 = new EventOutbox();
        TransferService s4 = new TransferService(fresh(), new IdempotencyStore(), o4);
        s4.transfer("T4","SAV2001","CUR3001",amt,false);
        o4.publishPending(false);                         // broker DOWN → 0 published
        assertTrue("BROKER_DOWN_NO_LOSS", o4.unpublished() == 1);
        int published = o4.publishPending(true);          // broker recovers
        assertTrue("BROKER_RECOVERY_PUBLISHED", published == 1 && o4.unpublished() == 0);
    }

    private static Ledger fresh() {
        Ledger l = new Ledger();
        l.open("SAV2001", new BigDecimal("1000000"));
        l.open("CUR3001", new BigDecimal("250000"));
        return l;
    }
    private static void assertEq(String contract, BigDecimal actual, BigDecimal expected) {
        boolean ok = actual.compareTo(expected) == 0;
        log.info(() -> (ok ? "PASS " : "FAIL ") + contract + " expected=" + expected + " actual=" + actual);
    }
    private static void assertTrue(String contract, boolean ok) {
        log.info(() -> (ok ? "PASS " : "FAIL ") + contract);
    }
}

